from pathlib import Path
import base64
import sys

if len(sys.argv) != 2:
    raise SystemExit("Usage: apply_psp_live_flogb_v0_5_7c3.py <ppsspp_repo>")

repo = Path(sys.argv[1]).resolve()

def require(rel):
    p = repo / rel
    if not p.exists():
        raise SystemExit(f"Missing expected path: {rel}")
    return p

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly 1 occurrence, found {count}")
    return text.replace(old, new, 1)

def replace_between(text, start, end, replacement, label):
    a = text.find(start)
    if a < 0:
        raise SystemExit(f"{label}: start marker missing")
    b = text.find(end, a + len(start))
    if b < 0:
        raise SystemExit(f"{label}: end marker missing")
    return text[:a] + replacement + text[b:]

debug = require("UI/DebugOverlay.cpp")
info = require("PSP_LIVE_FLOGB_BUILD_INFO.txt")
s = debug.read_text(encoding="utf-8")

for marker in (
    "WINNER ASSET V0.5.7C",
    "GetSCBDWinnerAssetTexture",
    "winner_asset_v057c/victory_intro.png",
    "winner_asset_v057c/pick_phase.png",
    "winner_asset_v057c/locked_in.png",
    "winner_asset_v057c/timeout.png",
    "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false",
    "SCBDVirtualInput::Process();",
    "DrawSCBDMatchTop5HUD",
):
    if marker not in s:
        raise SystemExit(f"V0.5.7C3 prerequisite missing: {marker}")

asset_dir = repo / "assets/scbd/winner_asset_v057c3"
asset_dir.mkdir(parents=True, exist_ok=True)

ASSETS = {
    "victory_final.png": "",
    "pick_final.png": "",
    "locked_final.png": "",
    "timeout_final.png": "",
    "splash_10_kratos.png": "",
}

for name, encoded in ASSETS.items():
    path = asset_dir / name
    path.write_bytes(base64.b64decode(encoded))
    if path.stat().st_size < 50000:
        raise SystemExit(f"V0.5.7C3 asset unexpectedly small: {name}")

RENDERER_B64 = ""
renderer = base64.b64decode(RENDERER_B64).decode("utf-8")

s = replace_between(
    s,
    "static Draw::Texture *g_scbdWinnerAssetTextures[4]",
    "static void DrawSCBDBoneMapper(",
    renderer + "\n\n",
    "replace V0.5.7C asset renderer with V0.5.7C3 final approved form",
)

s = replace_once(
    s,
    "WINNER ASSET V0.5.7C | approved production asset pack",
    "WINNER FINAL V0.5.7C3 | balanced avatar + Top5 safe form",
    "rename final winner lab",
)

debug.write_text(s, encoding="utf-8")
final = debug.read_text(encoding="utf-8")

required = (
    "GetSCBDWinnerFinalTexture",
    "winner_asset_v057c3/victory_final.png",
    "winner_asset_v057c3/pick_final.png",
    "winner_asset_v057c3/locked_final.png",
    "winner_asset_v057c3/timeout_final.png",
    "winner_asset_v057c3/splash_10_kratos.png",
    "DrawSCBDFinalRoster",
    "DrawSCBDFinalKratosSplash",
    "WINNER FINAL V0.5.7C3",
    "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false",
    "SCBDVirtualInput::Process();",
    "DrawSCBDMatchTop5HUD",
)
for marker in required:
    if marker not in final:
        raise SystemExit(f"V0.5.7C3 generated source missing: {marker}")

for forbidden in (
    "g_scbdWinnerAssetTextures[4]",
    "GetSCBDWinnerAssetTexture",
):
    if forbidden in final:
        raise SystemExit(f"V0.5.7C3 previous renderer survived: {forbidden}")

with info.open("a", encoding="utf-8") as f:
    f.write(
        "\nPSP Live FloGB V0.5.7C3 Final Asset Integration\n"
        "Approved balanced-avatar form integrated directly as final 1280x720 alpha canvases\n"
        "Top5 safe zones preserved left/right; center dim only\n"
        "Victory/Pick/Locked/Timeout use one coherent Royal Gold + Emerald scale system\n"
        "Pick live fields: username/team/score/timer + 28 live character portraits\n"
        "Locked In: dedicated Kratos large splash test + 28-character splash hook/fallback\n"
        "Timeout remains visual only; APK does not choose or fabricate Random\n"
        "Input Core V1, winner timing, tracker and Top5 HUD preserved\n"
    )

print("PSP Live FloGB V0.5.7C3 Final Asset Integration patch applied successfully.")
